import {test} from 'node:test';
import assert from 'node:assert/strict';
import {planGroom} from './groom_dashboard.mjs';
const now=new Date('2026-11-07T12:00:00Z');
const comment=(id,title,fp,days=0)=>({id,node_id:'IC_'+id,html_url:'https://github.com/o/r/issues/1#issuecomment-'+id,user:{login:'github-actions[bot]'},created_at:new Date(now-86400000*days).toISOString(),body:`## 🔍 Investigation: ${title}\n\n**Finding ID:** \`${fp}\`\n**Severity:** warning\n**Correlation:** test\n**Executive Summary:** Check the build setting.`});
const body='# Dashboard\n\n## 🆕 New Findings (1)\n\n### Active build\nFingerprint: `active`\n\n## ✅ Resolved Since Yesterday\n\nKeep this section exactly.\n\n## 📌 Existing Findings (0)\n\n<sub>Keep footer.</sub>\n';
test('missing island inserts active and resolved results; repeat is idempotent; non-bot text ignored',()=>{const bot=[comment(1,'Active build','active'),comment(2,'Resolved build','resolved')],human={...comment(3,'Fake','active'),user:{login:'person'}};const p=planGroom(body,[...bot,human],now);assert.equal(p.rows.length,2);assert.equal(p.rows[0][2],'✅ Done');assert.equal(p.rows[1][2],'✅ Resolved');assert.equal(p.body.split('## ✅ Resolved Since Yesterday')[1],body.split('## ✅ Resolved Since Yesterday')[1]);assert.equal(planGroom(p.body,[...bot,human],now).changed,false);assert.equal(p.hides.length,0);});
test('existing pending row preserved and only first island modified; duplicate/schema ambiguity fails',()=>{const island='## 🔍 Investigation Results\n\n| Finding | Severity | Status | Result |\n|---|---|---|---|\n| Active build | warning | 🔄 Dispatched | Pending |\n| Pending | warning | 🔄 Dispatched | No result |\n\n';const input=body.replace('## ✅ Resolved',island+'## ✅ Resolved'),p=planGroom(input,[comment(1,'Active build','active')],now);assert.equal(p.rows[1][3],'No result');assert.ok(p.body.includes('✅ Done'));assert.throws(()=>planGroom(input+'\n'+island,[],now));});
test('stale hiding respects72hours,7day strict boundary,28day cutoff,author and50budget',()=>{const old=[comment(1,'Resolved','gone',8),comment(2,'Boundary','gone',7),comment(3,'Fresh','gone',2)];const other={id:4,node_id:'IC_4',user:{login:'github-actions[bot]'},created_at:new Date(now-29*86400000).toISOString(),body:'Other bot note'};const p=planGroom(body,[...old,other,{...other,id:5,user:{login:'person'}}],now);assert.deepEqual(p.hides.map(x=>[x.id,x.reason]),[[1,'RESOLVED'],[4,'OUTDATED']]);const capped=planGroom(body,Array.from({length:55},(_,i)=>comment(i+10,'Old '+i,'gone'+i,8)),now);assert.equal(capped.hides.length,50);assert.equal(capped.skipped_hides,5);});
test('malformed bot investigations and ambiguous title matches require inspection',()=>{assert.throws(()=>planGroom(body,[{...comment(1,'Bad','bad'),body:'## 🔍 Investigation: Bad'}],now));const rows='## 🔍 Investigation Results\n| Finding | Severity | Status | Result |\n|---|---|---|---|\n| Same | warning | Pending | Pending |\n';assert.throws(()=>planGroom(body+rows,[comment(1,'Same','a'),comment(2,'Same','b')],now));});
